mapper.select:
select f.*, (select coach_name from pt_coach where id = f.coach_id) as coachName, (select s.storeName from store_address sa left join store s on s.storeId = sa.storeId where sa.storeAddrId = f.store_id) as storeName, (select product_name from pt_product where id = f.product_id) as productName, (select count(*) from pt_coach_fee_rule other_rule where other_rule.coach_id = f.coach_id and f.status = 1 and (other_rule.product_id = f.product_id or other_rule.product_id = 0 or f.product_id = 0) and (other_rule.store_id = f.store_id or other_rule.store_id = 0 or f.store_id = 0) and other_rule.rule_type <> f.rule_type and other_rule.status = 1) as conflictCount from pt_coach_fee_rule f
AND f.coach_id = #{coachId}
AND EXISTS (select 1 from pt_coach c where c.id = f.coach_id and c.coach_name LIKE concat('%', #{coachName}, '%'))
AND f.rule_type = #{ruleType} AND f.status = #{status} AND f.store_id = #{storeId} AND f.product_id = #{productId}
AND (f.store_id = 0 OR f.store_id IN (${storeIds}))
order by ${sidx} ${order}
order by f.id desc
limit #{offset}, #{limit}

select count(*) from pt_coach_fee_rule f

    AND f.coach_id = #{coachId}

        AND EXISTS (select 1 from pt_coach c
                    where c.id = f.coach_id
                      and c.coach_name LIKE concat('%', #{coachName}, '%'))

    AND f.rule_type = #{ruleType}
    AND f.status = #{status}
    AND f.store_id = #{storeId}
    AND f.product_id = #{productId}

        AND (f.store_id = 0 OR f.store_id IN (${storeIds}))

select count(*) from pt_coach_fee_rule
where coach_id = #{coachId} and product_id = #{productId}
  and store_id = #{storeId} and rule_type = #{ruleType}
AND id <> #{excludeId}

select count(*) from pt_coach_fee_rule
where coach_id = #{coachId}
  and (product_id = #{productId} or product_id = 0 or #{productId} = 0)
  and (store_id = #{storeId} or store_id = 0 or #{storeId} = 0)
  and rule_type <> #{ruleType} and status = 1
AND id <> #{excludeId}

select * from pt_coach_fee_rule
where coach_id = #{coachId} and status = 1
AND rule_type = #{ruleType}
